def transform(grid):
    h, w = len(grid), len(grid[0])
    separators = [(r, row[0]) for r, row in enumerate(grid)
                  if row[0] != 0 and all(x == row[0] for x in row)]
    sections = []
    gray_col = 0
    for i, (r, color) in enumerate(separators):
        if color == 9:
            continue
        end = separators[i + 1][0] if i + 1 < len(separators) else h
        section = grid[r + 1:end]
        height = sum(color in row for row in section)
        sections.append([color, height])
        for row in section:
            for c, x in enumerate(row):
                if x == 5:
                    gray_col = c
    marked = len(sections) - 1 - min(len(sections) - 1, gray_col * len(sections) // w)
    output = []
    for i, (color, height) in enumerate(sections):
        if height == 0:
            rank = 0
        else:
            rank = sum(1 for _, other in sections if other <= height)
        output.append([color] * rank + [0] * (3 - rank) + [9, 5 if i == marked else 0])
    return output
